<template>
 <div class="architecture-page">
  <ModelWorkspaceTabs class="architecture-workspace-tabs" />
  <header class="atlas-header">
   <div class="atlas-title"><el-icon><Share /></el-icon><div><el-input v-model="graph.name" :disabled="!editable" aria-label="架构名称" maxlength="128" /><p>五层 Hive 数仓 · Doris 查询副本 · API 服务</p></div></div>
   <div class="header-actions"><el-select v-model="currentProject" placeholder="选择所属项目" aria-label="架构所属项目" :disabled="!!graph.id || busy" @change="changeProject" style="width:180px"><el-option v-for="p in projects" :key="p.id" :label="p.name" :value="p.id" :disabled="!p.canEdit" /></el-select><span class="save-state">{{nodeDraftDirty?'有未应用的节点属性':dirty?'有未保存修改':graph.id?`已保存 · v${graph.revision}`:'新架构，尚未保存'}}</span><el-select v-model="documentId" :disabled="busy" placeholder="选择已保存架构" aria-label="已保存架构" @change="loadDocument" style="width:180px"><el-option v-for="d in documents" :key="d.id" :label="d.name" :value="d.id" /></el-select><el-button :disabled="busy || !projects.some(p=>p.canEdit)" @click="newDocument">新建架构</el-button><el-button @click="validate" :disabled="!currentProject" :loading="busy">校验</el-button><el-button type="primary" @click="save" :disabled="!editable" :loading="busy" v-hasPermi="['dp:model:edit']">保存架构</el-button></div>
  </header>
  <div v-if="graph.id && !editable" class="scope-strip" role="status">{{graph.projectId ? '当前项目仅可查看此架构' : '历史架构尚未确认项目归属，原内容保留为只读'}}</div>
  <div class="atlas-toolbar">
   <el-radio-group v-model="scope" aria-label="架构视图"><el-radio-button value="DEPLOYMENT">部署拓扑</el-radio-button><el-radio-button value="DATA">数据架构</el-radio-button></el-radio-group>
   <span class="view-explanation">{{scope==='DEPLOYMENT'?'服务、主机与连接关系；已登记不代表实时在线':'业务源 → Hive 五层 → Doris 查询副本 → API → 应用'}}</span>
   <div class="tools"><el-radio-group v-model="tool" size="small" aria-label="编辑工具"><el-radio-button value="select">选择 / 旋转</el-radio-button><el-radio-button value="move" :disabled="!editable">移动节点</el-radio-button><el-radio-button value="connect" :disabled="!editable">连接节点</el-radio-button></el-radio-group><el-button size="small" :disabled="!editable || !undoStack.length" @click="undo">撤销</el-button><el-button size="small" :disabled="!editable || !redoStack.length" @click="redo">重做</el-button><el-button size="small" @click="sceneRef?.fit()">适应画布</el-button><el-radio-group v-model="preset" size="small" aria-label="画布维度"><el-radio-button value="3d">3D 立体</el-radio-button><el-radio-button value="2.5d">2.5D 俯视</el-radio-button><el-radio-button value="2d">2D 平面</el-radio-button></el-radio-group></div>
  </div>
  <div v-if="error" class="error-strip" role="alert">{{error}}</div>
  <div v-if="connectFrom" class="connect-strip">已选择起点：{{findNode(connectFrom)?.label}}。请选择终点。<el-button link @click="connectFrom=null">取消连线</el-button></div>
  <div class="atlas-body">
   <aside class="resource-panel">
    <div class="resource-counts"><div><b>{{visibleNodes.length}}</b><span>节点</span></div><div><b>{{visibleEdges.length}}</b><span>连线</span></div><div><b>{{visibleNodes.filter(n=>n.state==='PLANNED').length}}</b><span>规划</span></div></div>
    <el-button type="primary" plain :disabled="!editable" @click="addVisible=true" class="wide">添加节点 / 导入资源</el-button>
    <el-input v-model="search" placeholder="搜索资源、主机或模型" clearable aria-label="搜索架构节点" />
    <section v-for="zone in zones" :key="zone"><h3>{{zoneLabel(zone)}}</h3><button v-for="n in filteredNodes.filter(n=>(n.zone||n.layer||'未分区')===zone)" :key="n.id" class="resource-item" :class="{active:selectedId===n.id}" @click="choose(n.id)"><span class="resource-symbol">{{symbol(n.kind)}}</span><span><strong>{{n.label}}</strong><small>{{n.engine || n.kind}} · {{stateLabel(n.state)}}</small></span></button></section>
    <el-empty v-if="!visibleNodes.length" description="添加主机、服务或数据节点开始规划" :image-size="60" />
    <div class="export-actions"><el-button @click="exportJson">导出 JSON</el-button><el-button :disabled="!editable" @click="importVisible=true">导入 JSON</el-button></div>
   </aside>
   <main class="atlas-canvas"><Scene ref="sceneRef" :nodes="graph.nodes" :edges="graph.edges" :scope="scope" :preset="preset" :tool="editable ? tool : 'select'" :selected-id="selectedId" @select="choose" @move="moveNode" @open="openResource" /></main>
   <aside class="property-panel">
    <el-tabs v-model="panelTab"><el-tab-pane label="节点属性" name="node">
     <template v-if="nodeDraft"><h3>{{nodeDraft.label}}</h3><p class="property-help">修改图上的说明和位置；不修改真实部署或模型定义。</p><el-form label-position="top" :disabled="!editable" @submit.prevent>
      <el-form-item label="节点名称"><el-input v-model="nodeDraft.label" aria-label="节点名称" maxlength="128" /></el-form-item>
      <div class="property-grid"><el-form-item label="节点类型"><el-select v-model="nodeDraft.kind" aria-label="节点类型"><el-option v-for="k in kinds" :key="k.value" :label="k.label" :value="k.value" /></el-select></el-form-item><el-form-item label="规划状态"><el-select v-model="nodeDraft.state" aria-label="节点状态"><el-option label="规划" value="PLANNED" /><el-option label="待确认" value="UNKNOWN" /><el-option v-if="nodeDraft.refId" label="已关联登记" value="REGISTERED" /></el-select></el-form-item></div>
      <el-form-item v-if="scope==='DATA'" label="数据阶段"><el-select v-model="nodeDraft.layer" :disabled="nodeDraft.refType==='MODEL'" aria-label="节点数据阶段" @change="changeDraftStage"><el-option v-for="s in stages" :key="s.id" :label="s.name" :value="s.id" /></el-select></el-form-item>
      <el-form-item label="计算 / 存储引擎"><el-input v-model="nodeDraft.engine" :disabled="nodeDraft.refType==='MODEL'" placeholder="例如 Hive、Doris、MySQL" aria-label="节点引擎" /></el-form-item>
      <el-form-item label="部署分区"><el-input v-model="nodeDraft.zone" placeholder="例如 Hive / HDFS" aria-label="节点分区" /></el-form-item>
      <el-form-item label="主机 / 服务地址"><el-input v-model="nodeDraft.address" placeholder="仅填写地址，不填写密码或令牌" aria-label="节点地址" /></el-form-item>
      <el-form-item v-if="scope==='DATA'" label="关联部署节点"><el-select v-model="nodeDraft.deploymentId" clearable filterable aria-label="关联部署节点"><el-option v-for="n in deploymentNodes" :key="n.id" :label="n.label" :value="n.id" /></el-select><el-button v-if="nodeDraft.deploymentId" link type="primary" @click="locateDeployment">在部署拓扑中定位</el-button></el-form-item>
      <div class="property-grid"><el-form-item label="X 坐标"><el-input-number v-model="nodeDraft.x" :min="-200" :max="200" :step=".5" controls-position="right" aria-label="节点X坐标" /></el-form-item><el-form-item label="Z 坐标"><el-input-number v-model="nodeDraft.z" :min="-200" :max="200" :step=".5" controls-position="right" aria-label="节点Z坐标" /></el-form-item></div>
      <el-form-item label="业务 / 部署说明"><el-input v-model="nodeDraft.description" type="textarea" :rows="3" maxlength="2000" aria-label="节点说明" /></el-form-item>
      <div class="property-actions"><el-button type="primary" @click="applyNode">应用属性</el-button><el-button v-if="nodeDraft.refId || nodeDraft.kind==='API'" @click="openResource(nodeDraft.id)">{{nodeDraft.refId?'打开关联资源':'注册 API'}}</el-button><el-button link type="danger" @click="deleteNode">移除节点</el-button></div>
     </el-form></template>
     <el-empty v-else description="点击三维节点或左侧资源查看属性" :image-size="70" />
    </el-tab-pane><el-tab-pane label="连线与任务" name="edge">
     <p class="property-help">数据加工逐层连接；DWT 内可建立星型关系。任务关联用于追溯，不会在保存图时执行。</p>
     <el-form label-position="top" :disabled="!editable" @submit.prevent><el-form-item label="起点"><el-select v-model="edgeDraft.source" filterable aria-label="连线起点"><el-option v-for="n in visibleNodes" :key="n.id" :label="n.label" :value="n.id" /></el-select></el-form-item><el-form-item label="终点"><el-select v-model="edgeDraft.target" filterable aria-label="连线终点"><el-option v-for="n in visibleNodes" :key="n.id" :label="n.label" :value="n.id" /></el-select></el-form-item><el-form-item label="关系类型"><el-select v-model="edgeDraft.kind" aria-label="连线类型"><el-option v-if="scope==='DEPLOYMENT'" label="部署 / 网络" value="NETWORK" /><template v-else><el-option label="加工 / 同步 / 服务" value="PROCESS" /><el-option label="主题星型关系" value="DIMENSION" /></template></el-select></el-form-item><el-form-item label="连线说明"><el-input v-model="edgeDraft.label" aria-label="连线说明" /></el-form-item><el-form-item label="关联已登记任务（可选）"><el-select v-model="edgeDraft.taskId" filterable clearable aria-label="关联任务"><el-option v-for="t in catalog.tasks" :key="t.id" :label="t.name" :value="t.id" /></el-select></el-form-item><el-button type="primary" @click="addEdge">{{edgeDraft.id?'更新连线':'添加连线'}}</el-button><el-button @click="resetEdge">清空</el-button></el-form>
     <h3>当前视图连线 · {{visibleEdges.length}}</h3><div v-for="e in visibleEdges" :key="e.id" class="edge-row"><button @click="editEdge(e)"><strong>{{findNode(e.source)?.label}} → {{findNode(e.target)?.label}}</strong><small>{{e.label || e.kind}} · {{stateLabel(e.state)}}{{e.taskId?` · 任务 #${e.taskId}`:''}}</small></button><el-button link type="danger" :disabled="!editable" @click="deleteEdge(e.id)" :aria-label="`移除连线 ${e.label}`">移除</el-button></div>
    </el-tab-pane></el-tabs>
   </aside>
  </div>
  <footer class="atlas-footer"><span><i class="legend registered" />已关联登记 <i class="legend planned" />规划 / 待配置</span><span>保存架构图不会启动同步、变更部署或发布 API。Doris 查询副本保留 ADS 业务口径。</span></footer>
  <el-dialog v-model="addVisible" title="添加节点 / 导入平台资源" width="620px" destroy-on-close>
   <el-tabs v-model="addMode"><el-tab-pane label="手工规划节点" name="manual"><el-form label-position="top"><el-form-item label="节点名称"><el-input v-model="newNode.label" aria-label="新节点名称" /></el-form-item><el-form-item label="节点类型"><el-select v-model="newNode.kind" aria-label="新节点类型"><el-option v-for="k in kinds" :key="k.value" :label="k.label" :value="k.value" /></el-select></el-form-item><el-form-item v-if="scope==='DATA'" label="数据阶段"><el-select v-model="newNode.layer" aria-label="新节点阶段"><el-option v-for="s in stages" :key="s.id" :label="s.name" :value="s.id" /></el-select></el-form-item><el-form-item label="分区名称"><el-input v-model="newNode.zone" aria-label="新节点分区" /></el-form-item></el-form><el-button type="primary" @click="addManual">添加规划节点</el-button></el-tab-pane>
   <el-tab-pane label="关联已登记资源" name="catalog"><el-form label-position="top"><el-form-item label="资源类型"><el-select v-model="importType" aria-label="导入资源类型"><el-option label="数据源" value="DATASOURCE" /><el-option v-if="scope==='DATA'" label="Hive 五层模型" value="MODEL" /><el-option label="API 服务" value="API" /></el-select></el-form-item><el-form-item label="选择平台资源"><el-select v-model="importId" filterable aria-label="选择平台资源"><el-option v-for="r in importOptions" :key="r.id" :label="r.name" :value="r.id" /></el-select></el-form-item><el-form-item v-if="scope==='DATA' && importType==='DATASOURCE'" label="数据阶段"><el-select v-model="importStage" aria-label="导入数据阶段"><el-option label="业务源" value="SOURCE" /><el-option label="Doris 查询副本" value="DORIS" /></el-select></el-form-item></el-form><el-button type="primary" @click="addResource">添加关联节点</el-button></el-tab-pane></el-tabs>
  </el-dialog>
  <el-dialog v-model="importVisible" title="导入架构 JSON" width="720px"><p>导入内容先作为未保存的新架构打开，不覆盖当前服务器版本。可使用本页导出的 JSON。</p><el-input v-model="importText" type="textarea" :rows="14" aria-label="架构JSON内容" /><template #footer><el-button @click="importVisible=false">取消</el-button><el-button type="primary" @click="importJson">载入架构</el-button></template></el-dialog>
 </div>
</template>
<script setup>
import ModelWorkspaceTabs from '@/components/ModelWorkspaceTabs/index.vue';
import {ref,computed,watch,onMounted,nextTick} from 'vue';
import {onBeforeRouteLeave,useRouter} from 'vue-router';
import {ElMessage,ElMessageBox} from 'element-plus';
import {Share} from '@element-plus/icons-vue';
import request from '@/utils/request';
import Scene from './Scene.vue';
import {stages,clone,uid,stateLabel,connectionError,createDefault,removeNode,importResource} from './graph';
const router=useRouter(),scope=ref('DEPLOYMENT'),preset=ref('3d'),tool=ref('select'),panelTab=ref('node'),search=ref(''),sceneRef=ref(),busy=ref(false),error=ref('');
const graph=ref({id:null,revision:0,name:'Hive 五层数仓与 Doris 服务架构',nodes:[],edges:[]});const catalog=ref({datasources:[],models:[],apis:[],tasks:[]}),documents=ref([]),documentId=ref(null),saved=ref(''),undoStack=ref([]),redoStack=ref([]),selectedId=ref(null),nodeDraft=ref(null),connectFrom=ref(null);
const projects=ref([]),currentProject=ref(null);
const editable=computed(()=>!!currentProject.value && !busy.value && !!projects.value.find(p=>p.id===currentProject.value)?.canEdit && (!graph.value.id || graph.value.canEdit));
const addVisible=ref(false),addMode=ref('manual'),newNode=ref({label:'',kind:'HOST',layer:'SOURCE',zone:''}),importType=ref('DATASOURCE'),importId=ref(null),importStage=ref('SOURCE'),importVisible=ref(false),importText=ref('');
const kinds=[{value:'HOST',label:'主机 / 服务器'},{value:'SERVICE',label:'服务 / 组件'},{value:'DATABASE',label:'数据库 / 集群'},{value:'TABLE',label:'数据表 / 模型'},{value:'API',label:'API 服务'},{value:'CLIENT',label:'应用 / 访问端'}];
const edgeDraft=ref({id:null,source:null,target:null,kind:'NETWORK',label:'',taskId:null,state:'PLANNED'});
const visibleNodes=computed(()=>graph.value.nodes.filter(n=>n.scope===scope.value));const deploymentNodes=computed(()=>graph.value.nodes.filter(n=>n.scope==='DEPLOYMENT'));const filteredNodes=computed(()=>visibleNodes.value.filter(n=>`${n.label} ${n.address} ${n.engine}`.toLowerCase().includes(search.value.toLowerCase())));const zones=computed(()=>[...new Set(filteredNodes.value.map(n=>n.zone||n.layer||'未分区'))].sort((a,b)=>scope.value==='DATA'?(stages.findIndex(s=>s.id===a)<0?99:stages.findIndex(s=>s.id===a))-(stages.findIndex(s=>s.id===b)<0?99:stages.findIndex(s=>s.id===b)):0));const visibleEdges=computed(()=>graph.value.edges.filter(e=>visibleNodes.value.some(n=>n.id===e.source)));const dirty=computed(()=>JSON.stringify(graph.value)!==saved.value);const importOptions=computed(()=>importType.value==='MODEL'?catalog.value.models:importType.value==='API'?catalog.value.apis:catalog.value.datasources);
const findNode=id=>graph.value.nodes.find(n=>n.id===id);const zoneLabel=id=>stages.find(s=>s.id===id)?.name || id;const symbol=kind=>({HOST:'▤',SERVICE:'▦',DATABASE:'◉',TABLE:'▥',API:'⇄',CLIENT:'▣'})[kind];
const api=(url,method='get',data)=>request({url:`/dp/architecture${url}`,method,data,headers:{repeatSubmit:false,hideErrorMessage:true}}).then(r=>r.data);
async function safely(fn){busy.value=true;error.value='';try{return await fn();}catch(e){error.value=e.message||String(e);ElMessage.error(error.value);}finally{busy.value=false;}}
function checkpoint(){undoStack.value.push(clone({name:graph.value.name,nodes:graph.value.nodes,edges:graph.value.edges}));if(undoStack.value.length>50)undoStack.value.shift();redoStack.value=[];}
function restore(from,to){if(!from.value.length)return;to.value.push(clone({name:graph.value.name,nodes:graph.value.nodes,edges:graph.value.edges}));Object.assign(graph.value,from.value.pop());refreshDraft();}
function undo(){if(!editable.value)return;restore(undoStack,redoStack);}function redo(){if(!editable.value)return;restore(redoStack,undoStack);}
function refreshDraft(){nodeDraft.value=selectedId.value && findNode(selectedId.value)?clone(findNode(selectedId.value)):null;}
function choose(id){if(editable.value && tool.value==='connect'){if(!connectFrom.value){connectFrom.value=id;selectedId.value=id;refreshDraft();return;}edgeDraft.value={...edgeDraft.value,id:null,source:connectFrom.value,target:id,kind:scope.value==='DEPLOYMENT'?'NETWORK':'PROCESS',state:'PLANNED'};connectFrom.value=null;panelTab.value='edge';addEdge();return;}selectedId.value=id;panelTab.value='node';refreshDraft();}
function moveNode(pos){if(!editable.value)return;checkpoint();Object.assign(findNode(pos.id),{x:Math.max(-200,Math.min(200,pos.x)),z:Math.max(-200,Math.min(200,pos.z))});selectedId.value=pos.id;refreshDraft();}
function changeDraftStage(){nodeDraft.value.zone=nodeDraft.value.layer;if(['ODS','DWD','DWS','DWT','ADS'].includes(nodeDraft.value.layer))nodeDraft.value.engine='Hive';else if(nodeDraft.value.layer==='DORIS')nodeDraft.value.engine='Doris';}
function applyNode(){if(!editable.value)return;if(!nodeDraft.value.label?.trim()){error.value='请填写节点名称';return;}checkpoint();Object.assign(findNode(selectedId.value),clone(nodeDraft.value));error.value='';ElMessage.success('节点属性已应用，请保存架构');}
function deleteNode(){if(!editable.value)return;checkpoint();removeNode(graph.value,selectedId.value);selectedId.value=null;nodeDraft.value=null;}
function addManual(){if(!editable.value)return;if(!newNode.value.label.trim()){ElMessage.error('请填写节点名称');return;}checkpoint();const stage=newNode.value.layer;const n={id:uid('node'),label:newNode.value.label,kind:newNode.value.kind,scope:scope.value,layer:scope.value==='DATA'?stage:'',engine:scope.value==='DATA' && ['ODS','DWD','DWS','DWT','ADS'].includes(stage)?'Hive':stage==='DORIS'?'Doris':'',zone:newNode.value.zone || (scope.value==='DATA'?stage:'新建分区'),x:0,z:20,state:'PLANNED',refType:null,refId:null,description:'',address:'',deploymentId:null};graph.value.nodes.push(n);addVisible.value=false;newNode.value.label='';choose(n.id);}
function addResource(){if(!editable.value)return;const r=importOptions.value.find(r=>r.id===importId.value);if(!r){ElMessage.error('请选择平台资源');return;}if(scope.value==='DATA' && importType.value==='DATASOURCE' && importStage.value==='DORIS' && r.engine.toUpperCase()!=='DORIS'){ElMessage.error('Doris 查询副本请选择 Doris 数据源');return;}checkpoint();const n=importResource(r,importType.value,scope.value,importType.value==='API'?'API':importStage.value,1);graph.value.nodes.push(n);addVisible.value=false;choose(n.id);}
function resetEdge(){edgeDraft.value={id:null,source:null,target:null,kind:scope.value==='DEPLOYMENT'?'NETWORK':'PROCESS',label:'',taskId:null,state:'PLANNED'};}
function addEdge(){if(!editable.value)return;const e=clone(edgeDraft.value);const message=connectionError(findNode(e.source),findNode(e.target),e.kind);if(message){error.value=message;ElMessage.error(message);return;}if(graph.value.edges.some(x=>x.id!==e.id&&x.source===e.source&&x.target===e.target&&x.kind===e.kind)){error.value='这条连线已存在';return;}checkpoint();e.state='PLANNED';if(e.id){graph.value.edges.splice(graph.value.edges.findIndex(x=>x.id===e.id),1,e);}else{e.id=uid('edge');graph.value.edges.push(e);}error.value='';resetEdge();ElMessage.success('连线已更新，请保存架构');}
function editEdge(e){edgeDraft.value=clone(e);panelTab.value='edge';}function deleteEdge(id){if(!editable.value)return;checkpoint();graph.value.edges=graph.value.edges.filter(e=>e.id!==id);resetEdge();}
async function locateDeployment(){const id=nodeDraft.value.deploymentId;scope.value='DEPLOYMENT';tool.value='select';await nextTick();selectedId.value=id;refreshDraft();}
const nodeDraftDirty=computed(()=>!!nodeDraft.value && JSON.stringify(nodeDraft.value)!==JSON.stringify(findNode(selectedId.value)));
async function canDiscard(){if(!dirty.value && !nodeDraftDirty.value)return true;try{await ElMessageBox.confirm('当前架构有未保存修改，是否继续？','未保存修改',{confirmButtonText:'继续',cancelButtonText:'返回编辑'});return true;}catch{return false;}}
function resetDrafts(){undoStack.value=[];redoStack.value=[];selectedId.value=null;nodeDraft.value=null;connectFrom.value=null;tool.value='select';resetEdge();}
async function loadCatalog(project){catalog.value=project ? await api(`/catalog?projectId=${project}`) : {datasources:[],models:[],apis:[],tasks:[]};}
async function loadDocument(id){if(!await canDiscard()){documentId.value=graph.value.id;return;}await safely(async()=>{const value=await api(`/documents/${id}`);await loadCatalog(value.projectId);graph.value=value;currentProject.value=value.projectId;documentId.value=value.id;saved.value=JSON.stringify(graph.value);resetDrafts();});}
async function initializeProject(project){await loadCatalog(project);graph.value={...createDefault(catalog.value),projectId:project,canEdit:!!projects.value.find(p=>p.id===project)?.canEdit};currentProject.value=project;documentId.value=null;saved.value=JSON.stringify(graph.value);resetDrafts();}
async function changeProject(project){if(!await canDiscard()){currentProject.value=graph.value.projectId;return;}await safely(()=>initializeProject(project));}
async function newDocument(){if(!await canDiscard())return;const project=projects.value.find(p=>p.id===currentProject.value&&p.canEdit)||projects.value.find(p=>p.canEdit);if(!project)return;await safely(()=>initializeProject(project.id));}
async function validate(){await safely(async()=>ElMessage.success(await api('/validate','post',graph.value)));}
async function save(){if(!editable.value)return;await safely(async()=>{graph.value=await api('/documents','post',graph.value);documentId.value=graph.value.id;saved.value=JSON.stringify(graph.value);documents.value=await api('/documents');ElMessage.success('架构已保存；实际资源和任务未变更');});}
function exportJson(){const blob=new Blob([JSON.stringify({format:'qdata-architecture-v1',document:graph.value},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='qdata-editable-architecture.json';a.click();URL.revokeObjectURL(url);}
async function importJson(){if(!editable.value)return;await safely(async()=>{const parsed=JSON.parse(importText.value);if(parsed.format!=='qdata-architecture-v1'||!parsed.document)throw new Error('不是本平台导出的架构格式');const d={...parsed.document,id:null,revision:0,projectId:currentProject.value,canEdit:true};await api('/validate','post',d);if(!await canDiscard())return;graph.value=d;documentId.value=null;saved.value='';resetDrafts();importVisible.value=false;});}
async function openResource(id){const n=findNode(id);if(!n)return;let path,query={};if(n.refType==='MODEL'){path='/dm/model/warehouse';query={modelId:n.refId};}else if(n.refType==='API'){path='/ds/api/detail';query={id:n.refId};}else if(n.kind==='API')path='/ds/api/add';else if(n.refType==='DATASOURCE'){path='/dpp/dataSource';query={type:1};}else return;await router.push({path,query});}
watch(scope,()=>{selectedId.value=null;nodeDraft.value=null;connectFrom.value=null;resetEdge();newNode.value.kind=scope.value==='DATA'?'TABLE':'HOST';if(scope.value==='DEPLOYMENT'&&importType.value==='MODEL')importType.value='DATASOURCE';});
watch(tool,()=>connectFrom.value=null);
onBeforeRouteLeave(async()=>await canDiscard());
onMounted(()=>safely(async()=>{[projects.value,documents.value]=await Promise.all([api('/projects'),api('/documents')]);const first=documents.value.find(d=>d.project_id==null || projects.value.find(p=>p.id===d.project_id)?.canRead);if(first){graph.value=await api(`/documents/${first.id}`);currentProject.value=graph.value.projectId;documentId.value=first.id;await loadCatalog(currentProject.value);saved.value=JSON.stringify(graph.value);}else {const project=projects.value.find(p=>p.canEdit)||projects.value.find(p=>p.canRead);if(project)await initializeProject(project.id);else saved.value=JSON.stringify(graph.value);}}));
</script>
